REVOKE EXECUTE ON FUNCTION public.create_player_profile(),public.record_audit_enqueue(),public.mail_enqueue() FROM PUBLIC,anon,authenticated;
REVOKE EXECUTE ON FUNCTION public.is_campaign_admin(),public.my_player_id(),public.in_campaign_house(text,boolean),public.save_campaign_record(uuid,integer,text,text),public.send_campaign_letter(uuid,text,text,text,uuid),public.reply_campaign_letter(uuid,text,uuid) FROM anon;
CREATE FUNCTION public.send_campaign_message(p_recipient text,p_subject text,p_content text,p_key uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.is_campaign_admin() THEN RAISE EXCEPTION 'Acesso não autorizado'; END IF; IF left(p_recipient,2)='p:' THEN RETURN public.send_campaign_letter(substring(p_recipient FROM 3)::uuid,NULL,p_subject,p_content,p_key); ELSIF left(p_recipient,2)='h:' THEN RETURN public.send_campaign_letter(NULL,substring(p_recipient FROM 3),p_subject,p_content,p_key); ELSE RAISE EXCEPTION 'Destinatário inválido'; END IF; END $$;
REVOKE ALL ON FUNCTION public.send_campaign_message(text,text,text,uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.send_campaign_message(text,text,text,uuid) TO authenticated;